<template><article class="card repair-card"><div><h3>{{repair.title}}</h3><p>{{repair.description}}</p><small>{{repair.type}} · {{repair.user?.nickname||'业主'}} · {{new Date(repair.created_at).toLocaleString()}}</small><p v-if="repair.return_reason" class="return-reason">退回原因：{{repair.return_reason}}</p><small v-if="repair.rework_count>0" class="rework-count">返工次数：{{repair.rework_count}}</small></div><div class="repair-side"><RepairStatusBadge :status="repair.status"/><div v-if="canAccept" class="accept-actions"><el-button size="small" type="success" @click="confirm">确认验收</el-button><el-button size="small" type="warning" @click="sendBack">退回返工</el-button></div></div></article></template><script setup lang="ts">import{computed}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import type{Repair}from'../../types';import{authStore}from'../../stores/authStore';import{confirmRepair,returnRepair}from'../../api/repair';import RepairStatusBadge from'./RepairStatusBadge.vue';const p=defineProps<{repair:Repair}>();const emit=defineEmits<{refresh:[]}>();const canAccept=computed(()=>p.repair.status==='acceptance'&&authStore.user?.id===p.repair.user_id);async function confirm(){try{await confirmRepair(p.repair.id);ElMessage.success('工单已确认验收并归档关闭');emit('refresh')}catch(e){ElMessage.error((e as Error).message)}}async function sendBack(){try{const{value}=await ElMessageBox.prompt('请填写退回原因','退回返工',{inputPlaceholder:'例如：问题仍未解决',inputValidator:v=>(v&&v.trim().length>=2)||'退回原因至少 2 个字'});await returnRepair(p.repair.id,value.trim());ElMessage.success('工单已退回返工');emit('refresh')}catch(e){if(e!=='cancel')ElMessage.error((e as Error).message)}}</script>
